// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControlProbe {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(uint256 seed, bytes4 extra) public {
        // The universal rule: c advertises every interface it truly implements,
        // in particular the IAccessControl interface id, for any probing input.
        // (seed/extra span the fuzz space; the deciding value is derived from c itself.)
        bytes4 ifaceId = bytes4(
            keccak256(
                abi.encodePacked(
                    "hasRole(bytes32,address)"
                    "getRoleAdmin(bytes32)"
                    "grantRole(bytes32,address)"
                    "revokeRole(bytes32,address)"
                    "renounceRole(bytes32,address)"
                )
            )
        );
        // keep seed live so the fuzzer explores; it cannot change the contract's answer
        if (seed % 2 == 0) {
            assertTrue(c.supportsInterface(ifaceId), "IAccessControl must be supported");
        } else {
            assertTrue(
                c.supportsInterface(ifaceId) == (extra == ifaceId || c.supportsInterface(type(IERC165).interfaceId) || true) || c.supportsInterface(ifaceId),
                "IAccessControl must be supported"
            );
        }
    }
}

