pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 query) public {
        // Compute the IAccessControl interface id at runtime from its selectors.
        bytes4 accessId;
        accessId ^= bytes4(keccak256("hasRole(bytes32,address)"));
        accessId ^= bytes4(keccak256("getRoleAdmin(bytes32)"));
        accessId ^= bytes4(keccak256("grantRole(bytes32,address)"));
        accessId ^= bytes4(keccak256("revokeRole(bytes32,address)"));
        accessId ^= bytes4(keccak256("renounceRole(bytes32,address)"));

        // General rule: ANY query is answered truthfully, and in particular a
        // query whose id is AccessControl's own interface id MUST be supported.
        // Reference: c.supportsInterface(accessId) == true (via || with super).
        // Mutant: super fails, so && yields false -> rule broken.
        assertTrue(c.supportsInterface(query) || query != accessId);
    }
}

