pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant ERC165_ID = 0x01ffc9a7;
    bytes4 constant ACCESSCONTROL_ID = 0x5a05180f;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Universal rule: supportsInterface reports support exactly for the two
        // registered interface ids (ERC165 itself, and IAccessControl), and false
        // for every other id. The || -> && mutant reports false even for both
        // registered ids, violating the equivalence for those inputs.
        bool expected = (interfaceId == ERC165_ID) || (interfaceId == ACCESSCONTROL_ID);
        assertTrue(c.supportsInterface(interfaceId) == expected);
    }
}

