import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IERC165} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 seed) public {
        bytes4 id = bytes4(uint32(uint160(seed)));
        bool supported = c.supportsInterface(id);
        bool admissible = id == IERC165.supportsInterface.selector || id == type(IERC165).interfaceId || id == type(IAccessControl).interfaceId;
        assertTrue(!supported || admissible, "supportsInterface must only report IERC165/IAccessControl ids");
    }
}

