pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 id) public {
        // Interface ids recomputed from their canonical signatures (ERC-165).
        bytes4 iacId =
            bytes4(keccak256("hasRole(bytes32,address)")) ^
            bytes4(keccak256("getRoleAdmin(bytes32)")) ^
            bytes4(keccak256("grantRole(bytes32,address)")) ^
            bytes4(keccak256("revokeRole(bytes32,address)")) ^
            bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 ierc165Id = bytes4(keccak256("supportsInterface(bytes4)"));

        // General rule: C advertises support iff the id is one of its two inherited
        // interface ids (IAccessControl or IERC165); no other id is ever supported.
        bool expected = (id == iacId) || (id == ierc165Id);
        assertTrue(c.supportsInterface(id) == expected);
    }
}

