pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selector, uint256 salt) public {
        // Admissible domain: the interface ids C is required to advertise.
        // The fuzzer freely selects which one is probed (plus an unused salt keeps
        // the input space wide and non-degenerate).
        bytes4 id = (uint256(keccak256(abi.encodePacked(selector))) % 2 == 0)
            ? type(IERC165).interfaceId
            : type(IAccessControl).interfaceId;
        salt;

        bool supported = c.supportsInterface(id);

        // General rule: for every interface id the contract claims its own
        // conformance to (IERC165 and IAccessControl), supportsInterface returns
        // true. The mutant drops the IAccessControl branch, so it returns false
        // for IAccessControl's id while the reference returns true.
        assertTrue(supported);
    }
}

