pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 immutable IAC_ID;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    constructor() {
        bytes4 sel = bytes4(keccak256("hasRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
            ^ bytes4(keccak256("grantRole(bytes32,address)"))
            ^ bytes4(keccak256("revokeRole(bytes32,address)"))
            ^ bytes4(keccak256("renounceRole(bytes32,address)"));
        IAC_ID = sel ^ type(IERC165).interfaceId;
    }

    function testFuzz_property(bytes4 id) public {
        bool supported = c.supportsInterface(id);
        bool expected = (id == type(IERC165).interfaceId) || (id == IAC_ID);
        assertTrue(supported == expected);
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
